// Hosted Function Infrastructure

struct RocOps;

typedef void (*HostedFn)(void);


// Hosted Function Count

#define HOSTED_FUNCTION_COUNT 3


#define HOSTED_IDX_HOST_STDERR_LINE 0
#define HOSTED_IDX_HOST_STDIN_LINE 1
