// Argument Structures


/**
 * Arguments for Host.stderr_line!
 * Roc signature: Str => Try({}, [StderrErr(Str)])
 * Refcounted fields are owned by the hosted function.
 */
typedef struct {
    RocStr arg0;
} HostStderrLineArgs;

/**
 * Arguments for Host.stdout_line!
 * Roc signature: Str => Try({}, [StdoutErr(Str)])
 * Refcounted fields are owned by the hosted function.
 */
